(function(){
  function tokenize(s){
    s=String(s||'').replace(/\\\r?\n/g,' ');
    var out=[],cur='',q=null,has=false;
    for(var i=0;i<s.length;i++){
      var c=s[i];
      if(q){ if(c===q){q=null;} else {cur+=c;} continue; }
      if(c==='"'||c==="'"){ q=c; has=true; continue; }
      if(/\s/.test(c)){ if(cur||has){out.push(cur);cur='';has=false;} continue; }
      cur+=c;
    }
    if(cur||has)out.push(cur);
    return out;
  }
  var LIST={'-p':'ports','--publish':'ports','-v':'volumes','--volume':'volumes','--mount':'volumes',
            '-e':'environment','--env':'environment','-l':'labels','--label':'labels',
            '--device':'devices','--add-host':'extra_hosts','--dns':'dns','--cap-add':'cap_add',
            '--cap-drop':'cap_drop','--expose':'expose','--link':'links','--tmpfs':'tmpfs',
            '--security-opt':'security_opt','--sysctl':'sysctls','--network':'networks','--net':'networks'};
  var SCALAR={'--name':'container_name','--restart':'restart','-w':'working_dir','--workdir':'working_dir',
              '--entrypoint':'entrypoint','-u':'user','--user':'user','--hostname':'hostname',
              '-m':'mem_limit','--memory':'mem_limit','--cpus':'cpus','--shm-size':'shm_size',
              '--pid':'pid','--ipc':'ipc','--stop-signal':'stop_signal','--domainname':'domainname'};
  var BOOL={'--privileged':'privileged','--init':'init','--read-only':'read_only'};
  var IGNORE={'-d':1,'--detach':1,'--rm':1,'-i':1,'-t':1,'-it':1,'-ti':1,'--tty':1,'--interactive':1};

  function need(f){ return LIST[f]!=null||SCALAR[f]!=null; }

  function runToCompose(cmd,opt){
    opt=opt||{};
    var tk=tokenize(cmd);
    if(!tk.length) return {error:'请输入 docker run 命令'};
    var i=0;
    if(tk[0]==='docker') i++;
    if(tk[i]==='container') i++;
    if(tk[i]==='run') i++; else if(tk[0]==='docker') return {error:'仅支持 docker run 命令'};
    var svc={},image=null,args=[],warn=[];
    for(;i<tk.length;i++){
      var t=tk[i];
      if(image!=null){ args.push(t); continue; }
      if(t.charAt(0)!=='-'){ image=t; continue; }
      var flag=t,val=null,eq=t.indexOf('=');
      if(eq>0&&t.charAt(1)==='-'){ flag=t.slice(0,eq); val=t.slice(eq+1); }
      if(IGNORE[flag]!=null&&val==null){ continue; }
      if(BOOL[flag]!=null){ svc[BOOL[flag]]=true; continue; }
      if(need(flag)){
        if(val==null){ val=tk[++i]; }
        if(val==null){ warn.push(flag+' 缺少取值'); continue; }
        if(LIST[flag]!=null){ var k=LIST[flag]; (svc[k]=svc[k]||[]).push(val); }
        else { svc[SCALAR[flag]]=val; }
        continue;
      }
      warn.push('未识别参数 '+flag+'（已忽略）');
    }
    if(!image) return {error:'未找到镜像名'};
    var name=opt.service||svc.container_name||image.split('/').pop().split(':')[0].replace(/[^a-zA-Z0-9_-]/g,'')||'app';
    var yaml='services:\n  '+name+':\n    image: '+image+'\n';
    var order=['container_name','restart','entrypoint','user','working_dir','hostname','domainname',
               'mem_limit','cpus','shm_size','pid','ipc','stop_signal','privileged','init','read_only'];
    for(var oi=0;oi<order.length;oi++){
      var ok2=order[oi];
      if(svc[ok2]!=null) yaml+='    '+ok2+': '+fmt(svc[ok2])+'\n';
    }
    var lists=['ports','volumes','environment','labels','devices','extra_hosts','dns','cap_add',
               'cap_drop','expose','links','tmpfs','security_opt','sysctls','networks'];
    for(var li=0;li<lists.length;li++){
      var lk=lists[li];
      if(!svc[lk]) continue;
      yaml+='    '+lk+':\n';
      for(var vi=0;vi<svc[lk].length;vi++) yaml+='      - '+quote(svc[lk][vi])+'\n';
    }
    if(args.length) yaml+='    command: '+quote(args.join(' '))+'\n';
    return {value:{yaml:yaml,service:name,image:image,warn:warn}};
  }
  function fmt(v){ if(v===true) return 'true'; return quote(String(v)); }
  function quote(s){
    s=String(s);
    if(/^[A-Za-z0-9_./:@=-]+$/.test(s)&&!/^\d+:\d+$/.test(s)&&!/^\d+$/.test(s)) return s;
    return '"'+s.replace(/"/g,'\\"')+'"';
  }

  function unq(s){
    s=String(s).trim();
    if((s.charAt(0)==='"'&&s.slice(-1)==='"')||(s.charAt(0)==="'"&&s.slice(-1)==="'")) return s.slice(1,-1);
    return s;
  }
  function composeToRun(yamlText){
    var lines=String(yamlText||'').split(/\r?\n/),si=-1;
    for(var i=0;i<lines.length;i++){ if(/^\s*services\s*:\s*$/.test(lines[i])){ si=i; break; } }
    if(si<0) return {error:'未找到 services: 段'};
    var name=null,base=0,svc={},key=null;
    for(var j=si+1;j<lines.length;j++){
      var ln=lines[j];
      if(!ln.trim()||/^\s*#/.test(ln)) continue;
      var ind=ln.length-ln.replace(/^\s+/,'').length;
      var body=ln.trim();
      if(name==null){
        if(/:$/.test(body)){ name=body.slice(0,-1).trim(); base=ind; }
        continue;
      }
      if(ind<=base){ break; }
      if(body.charAt(0)==='-'){
        if(key) (svc[key]=svc[key]||[]).push(unq(body.slice(1).trim()));
        continue;
      }
      var m=body.match(/^([A-Za-z0-9_]+)\s*:\s*(.*)$/);
      if(!m) continue;
      key=m[1];
      if(m[2]==='') { svc[key]=[]; } else { svc[key]=unq(m[2]); key=null; }
    }
    if(name==null) return {error:'services 下没有服务'};
    if(!svc.image) return {error:'服务 '+name+' 缺少 image'};
    var out=['docker run'];
    out.push('-d');
    if(svc.container_name) out.push('--name '+svc.container_name);
    var map={ports:'-p',volumes:'-v',environment:'-e',labels:'--label',devices:'--device',
             extra_hosts:'--add-host',dns:'--dns',cap_add:'--cap-add',cap_drop:'--cap-drop',
             expose:'--expose',links:'--link',tmpfs:'--tmpfs',security_opt:'--security-opt',
             sysctls:'--sysctl',networks:'--network'};
    for(var mk in map){ if(!Array.isArray(svc[mk])) continue;
      for(var q=0;q<svc[mk].length;q++) out.push(map[mk]+' '+sh(svc[mk][q])); }
    var sc={restart:'--restart',working_dir:'-w',user:'-u',hostname:'--hostname',
            mem_limit:'-m',cpus:'--cpus',shm_size:'--shm-size',pid:'--pid',ipc:'--ipc',
            entrypoint:'--entrypoint',stop_signal:'--stop-signal'};
    for(var sk in sc){ if(typeof svc[sk]==='string') out.push(sc[sk]+' '+sh(svc[sk])); }
    if(svc.privileged==='true') out.push('--privileged');
    if(svc.init==='true') out.push('--init');
    if(svc.read_only==='true') out.push('--read-only');
    out.push(svc.image);
    if(typeof svc.command==='string'&&svc.command) out.push(svc.command);
    return {value:{cmd:out.join(' '),service:name}};
  }
  function sh(s){ return /[\s"'$]/.test(s)?("'"+String(s).replace(/'/g,"'\\''")+"'"):s; }

  var API={tokenize:tokenize,runToCompose:runToCompose,composeToRun:composeToRun};
  if(typeof module!=='undefined'&&module.exports)module.exports=API;
  if(typeof window!=='undefined')window.__ComposeForge__=API;
})();
